// Native test (plain `cargo test`): the program's hashing must reproduce the
// vectors generated by the TypeScript auction engine (auction/scripts/gen-vectors.ts).

use snark_claim::merkle;

fn hex32(s: &str) -> [u8; 32] {
    let v = hex(s);
    v.try_into().expect("32 bytes")
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn vectors() -> serde_json::Value {
    serde_json::from_str(include_str!("fixtures/merkle_vectors.json")).unwrap()
}

#[test]
fn commitments_match_the_typescript_engine() {
    for c in vectors()["claims"].as_array().unwrap() {
        let pubkey = hex32(c["claim_pubkey"].as_str().unwrap());
        let salt: [u8; 16] = hex(c["salt"].as_str().unwrap()).try_into().unwrap();
        assert_eq!(merkle::commitment(&pubkey, &salt), hex32(c["commitment"].as_str().unwrap()));
    }
}

#[test]
fn every_allocation_proves_against_the_typescript_root() {
    let v = vectors();
    let root = hex32(v["root"].as_str().unwrap());
    for c in v["claims"].as_array().unwrap() {
        let commitment = hex32(c["commitment"].as_str().unwrap());
        let tokens: u64 = c["tokens"].as_str().unwrap().parse().unwrap();
        let proof: Vec<[u8; 32]> = c["proof"].as_array().unwrap().iter().map(|p| hex32(p.as_str().unwrap())).collect();
        assert!(merkle::verify(merkle::leaf(&commitment, tokens), &proof, &root));
        assert!(!merkle::verify(merkle::leaf(&commitment, tokens + 1), &proof, &root), "a different amount must fail");
    }
}

#[test]
fn overlong_proofs_are_refused() {
    let proof = vec![[0u8; 32]; merkle::MAX_PROOF_LEN + 1];
    assert!(!merkle::verify([0u8; 32], &proof, &[0u8; 32]));
}
